CREATE OR REPLACE FUNCTION public.fn_job_daily_cap() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE daily integer; hourly integer; cap integer; BEGIN PERFORM pg_advisory_xact_lock(hashtext('job_cap:'||NEW.business_id::text)); cap:=CASE WHEN public.fn_effective_plan(NEW.business_id)='pro' THEN 300 ELSE 50 END; SELECT count(*) FILTER(WHERE created_at>=now()-interval '1 hour'),count(*) FILTER(WHERE created_at>=date_trunc('day',now())) INTO hourly,daily FROM public.referral_triggers WHERE business_id=NEW.business_id; IF hourly>=120 OR daily>=cap THEN RAISE EXCEPTION 'job_ask_limit'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_job_daily_cap BEFORE INSERT ON public.referral_triggers FOR EACH ROW EXECUTE FUNCTION public.fn_job_daily_cap();
CREATE OR REPLACE FUNCTION public.fn_request_bucket() RETURNS text LANGUAGE plpgsql STABLE SET search_path=public,pg_catalog AS $$ DECLARE h jsonb; BEGIN BEGIN h:=nullif(current_setting('request.headers',true),'')::jsonb; EXCEPTION WHEN OTHERS THEN h:='{}'::jsonb; END; RETURN md5(coalesce(auth.uid()::text,nullif(split_part(coalesce(h->>'x-forwarded-for','anonymous'),',',1),''),'anonymous')); END $$;